{
  "omision_de_tema_relevante": {
    "definicion": "Consiste en excluir deliberadamente de la cobertura informativa un asunto de importancia pública, de modo que la audiencia no lo perciba como prioritario. La omisión puede deberse a intereses editoriales, presiones externas o sesgos cognitivos, y sirve para moldear la percepción de lo que merece atención.",
    "ejemplo": "En la cobertura de la crisis migratoria en la frontera sur de EE. UU. en abril 2024, varios medios nacionales omitieron mencionar el aumento de la violencia contra migrantes, centrándose solo en la respuesta gubernamental.",
    "como_detectarla": [
      "1. Identificar los principales hechos relevantes a través de fuentes internacionales o bases de datos independientes.",
      "2. Comparar la lista de hechos con los temas tratados en el medio analizado.",
      "3. Detectar ausencias sistemáticas de temas que aparecen en fuentes externas y que son de alto impacto social."
    ]
  },
  "infotainment_con_enfasis_en_figuras_publicas": {
    "definicion": "Mezcla de información y entretenimiento que privilegia la presencia de celebridades, políticos o influencers, a menudo simplificando o sensacionalizando la noticia para captar la audiencia, en vez de profundizar en el contenido factual.",
    "ejemplo": "Durante la campaña presidencial de España 2024, el programa \"Sálvame\" dedicó varias horas a comentar los outfits de los candidatos en los debates, relegando el análisis de sus propuestas económicas.",
    "como_detectarla": [
      "1. Analizar la proporción de tiempo o espacio dedicado a la personalidad frente al contenido informativo.",
      "2. Revisar si los hechos se presentan mediante anécdotas o chismes en lugar de datos verificables.",
      "3. Verificar si el tono es sensacionalista y busca generar emociones más que comprensión."
    ]
  },
  "agenda_setting_centrado_en_politica_y_deporte": {
    "definicion": "Técnica que determina la importancia que el público asigna a ciertos asuntos al darles mayor frecuencia y prominencia, enfocándose principalmente en la agenda política y deportiva para desviar la atención de otros temas críticos.",
    "ejemplo": "En la primera semana de julio 2024, los principales canales de televisión en México dedicaron el 70 % de su horario de noticias a la cobertura de la campaña electoral y al inicio del Mundial Sub‑20, mientras que la crisis del agua en el norte del país recibió apenas menciones breves.",
    "como_detectarla": [
      "1. Medir la cuota de tiempo o espacio de cada tema en la programación semanal.",
      "2. Comparar la distribución temática con indicadores de relevancia social (por ejemplo, datos de salud o economía).",
      "3. Identificar patrones recurrentes que privilegien política y deporte sobre otras áreas."
    ]
  },
  "enfoque_selectivo_en_controversias_politicas": {
    "definicion": "Selección intencional de episodios o ángulos de una controversia política que favorecen una narrativa específica, omitiendo datos o perspectivas contrarias para influir en la opinión pública.",
    "ejemplo": "En la cobertura de las protestas contra la reforma laboral en Chile (marzo 2024), varios diarios resaltaron los incidentes violentos de un pequeño grupo de manifestantes, mientras minimizaron los reclamos de la mayoría pacífica y las violaciones de derechos humanos por parte de la policía.",
    "como_detectarla": [
      "1. Recopilar múltiples fuentes sobre la misma controversia y listar los hechos reportados.",
      "2. Identificar qué hechos aparecen consistentemente y cuáles son ausentes o marginales en el medio objetivo.",
      "3. Evaluar si la selección favorece una postura ideológica o política específica."
    ]
  },
  "omision_de_contenido_tecnologico": {
    "definicion": "Práctica editorial que consiste en excluir o reducir la cobertura de avances, riesgos o impactos de la tecnología, a menudo para evitar debates sobre regulación, privacidad o cambios estructurales.",
    "ejemplo": "A principios de octubre 2024, los principales periódicos españoles apenas mencionaron el descubrimiento de una vulnerabilidad crítica en el software de los sistemas de voto electrónico, centrando la información en la campaña electoral.",
    "como_detectarla": [
      "1. Revisar bases de datos de incidentes tecnológicos (por ejemplo, CVE, informes de ciberseguridad) del mismo periodo.",
      "2. Contrastar la presencia de esos eventos en medios especializados versus medios generalistas.",
      "3. Detectar la ausencia sistemática de menciones a tecnología cuando otras áreas sí reciben cobertura extensa."
    ]
  }
}
